function configureHotelPosition(){
 for(const lang of ['pt','es','en']){
  const p=hotelPosition[lang],t=copy[lang];
  for(const key of ['title','desc','eyebrow','headline','hero','heroLink','heroFoot','opportunity','oppTitle','oppLead','statement','symptoms','intervention','servicesTitle','servicesLead','contactTitle','contactCopy','placeholder']) t[key]=p[key];
  t.services=p.services.map(s=>[...s,'']);
 }
}
function hotelValueSection(lang){const p=hotelPosition[lang];return `<section class="section" id="experience"><div class="wrap"><span class="eyebrow">${p.experienceLabel}</span><h2>${p.experienceTitle}</h2><p class="wide-lead">${p.experienceIntro}</p><div class="plan-grid">${p.benefits.map((b,i)=>`<article><span class="step-number">0${i+1}</span><h3>${b[0]}</h3><p>${b[1]}</p></article>`).join('')}</div><p class="section-note">${p.experienceNote}</p></div></section>`;}
